import { version } from "../package.json";
import { GAME_STATE_VERSION } from "./game/gameState";
import { REPLAY_FORMAT_VERSION, RULES_VERSION } from "./game/replay";

/**
 * The game's versions, shown in the footer and the manual, and in the README's versions table
 * (generated by `scripts/versions.ts`, checked by a test).
 *
 * - `app`: the game (`package.json`). Bump it for a release; the manual and README describe it.
 * - `rules`: what a frame does; bumped by `vp run golden:update` when play changes.
 * - `state`: the saved state's shape; bumped the same way when it changes.
 * - `replayFormat`: the replay file's layout.
 */
export const VERSIONS = {
  app: version,
  rules: RULES_VERSION,
  state: GAME_STATE_VERSION,
  replayFormat: REPLAY_FORMAT_VERSION,
} as const;

/**
 * The branch a preview build was made from (GitHub Pages builds every branch: see
 * .github/workflows/pages.yml); empty for the released game and local builds.
 */
export const BUILD_BRANCH = (import.meta.env.VITE_BUILD_BRANCH as string | undefined) ?? "";

/** "v0.1.0" */
export const APP_VERSION_LABEL = `v${version}`;
